item.command:
/bin/zsh -lc "shasum -a 256 <<'EOF'
import clsx from \"clsx\";
import \"./entry-tree.css\";

/**
 * @summary route 전용 entry tree 속성
 */
interface EntryTreeProps {
  /**
   * @field 렌더링할 entry 목록
   */
  entries: Array<{id: string; label: string}>;
  /**
   * @field 선택된 entry ID
   */
  selectedId?: string;
}

export const EntryTree = (props: EntryTreeProps) => {
  const {entries, selectedId} = props;

  return (
    <ul
      className={clsx(
        \"rt_entriesEntryTree__tree\",
        selectedId && \"rt_entriesEntryTree__tree--selected\",
      )}
    >
      {entries.map((entry) => (
        <li key={entry.id}>{entry.label}</li>
      ))}
    </ul>
  );
};
EOF
shasum -a 256 <<'EOF'
.rt_entriesEntryTree__tree {
  list-style: none;
}

.rt_entriesEntryTree__tree--selected {
  font-weight: 600;
}
EOF"

